alter table public.profiles add column if not exists is_admin boolean not null default false;
alter table public.material_decks add column if not exists visibility text not null default 'private';
alter table public.material_decks add column if not exists submitted_at timestamptz;
alter table public.material_decks add column if not exists approved_at timestamptz;
alter table public.material_decks add column if not exists rejected_reason text;
alter table public.material_decks add column if not exists created_by_user_id uuid references public.profiles(id);
alter table public.material_decks add column if not exists copy_count int not null default 0;
alter table public.material_decks add column if not exists updated_at timestamptz not null default now();
alter table public.word_lists add column if not exists visibility text not null default 'private';
alter table public.word_lists add column if not exists submitted_at timestamptz;
alter table public.word_lists add column if not exists approved_at timestamptz;
alter table public.word_lists add column if not exists rejected_reason text;
alter table public.word_lists add column if not exists created_by_user_id uuid references public.profiles(id);
alter table public.word_lists add column if not exists copy_count int not null default 0;
alter table public.word_lists add column if not exists updated_at timestamptz not null default now();
update public.material_decks set visibility=case when is_public then'unlisted'else'private'end,created_by_user_id=coalesce(created_by_user_id,user_id)where visibility='private';
update public.word_lists set visibility=case when is_public then'unlisted'else'private'end,created_by_user_id=coalesce(created_by_user_id,user_id)where visibility='private';
alter table public.material_attempts alter column rating drop not null;
alter table public.material_attempts add column if not exists action text not null default 'review';
alter table public.word_attempts alter column rating drop not null;
alter table public.word_attempts add column if not exists action text not null default 'review';
create or replace function public.is_admin()returns boolean language sql stable security definer set search_path=public as $$select coalesce((select is_admin from profiles where id=auth.uid()),false)$$;
drop policy if exists "material decks public read" on public.material_decks;create policy "material decks public read" on public.material_decks for select using(visibility in('unlisted','approved'));
drop policy if exists "material nodes public read" on public.material_nodes;create policy "material nodes public read" on public.material_nodes for select using(exists(select 1 from public.material_decks d where d.id=deck_id and d.visibility in('unlisted','approved')));
drop policy if exists "word lists public read" on public.word_lists;create policy "word lists public read" on public.word_lists for select using(visibility in('unlisted','approved'));
drop policy if exists "word cards public read" on public.word_cards;create policy "word cards public read" on public.word_cards for select using(exists(select 1 from public.word_lists l where l.id=list_id and l.visibility in('unlisted','approved')));
create policy "admin material review" on public.material_decks for select using(public.is_admin());create policy "admin material update" on public.material_decks for update using(public.is_admin());
create policy "admin material nodes review" on public.material_nodes for select using(public.is_admin());
create policy "admin cards review" on public.word_lists for select using(public.is_admin());create policy "admin cards update" on public.word_lists for update using(public.is_admin());
create policy "admin word cards review" on public.word_cards for select using(public.is_admin());
create or replace function public.review_target(p_type text,p_id uuid,p_rating rating,p_unknown boolean)returns void language plpgsql security definer set search_path=public as $$declare days int;begin if p_type='material'then if not exists(select 1 from material_nodes n join material_decks d on d.id=n.deck_id where n.id=p_id and n.node_type='item'and d.user_id=auth.uid())then raise exception'not allowed';end if;if p_rating is null then insert into material_item_states(user_id,material_node_id,unknown_flag)values(auth.uid(),p_id,p_unknown)on conflict(user_id,material_node_id)do update set unknown_flag=p_unknown,updated_at=now();insert into material_attempts(user_id,material_node_id,rating,unknown_flag,action)values(auth.uid(),p_id,null,p_unknown,'check');else days:=case p_rating when'again'then 0 when'hard'then 1 when'good'then 3 else 7 end;insert into material_item_states(user_id,material_node_id,last_rating,unknown_flag,review_count,due_at,next_review_date)values(auth.uid(),p_id,p_rating,p_unknown,1,now()+make_interval(days=>days),current_date+days)on conflict(user_id,material_node_id)do update set last_rating=p_rating,unknown_flag=p_unknown,review_count=material_item_states.review_count+1,due_at=now()+make_interval(days=>days),next_review_date=current_date+days,updated_at=now();insert into material_attempts(user_id,material_node_id,rating,unknown_flag,action)values(auth.uid(),p_id,p_rating,p_unknown,'review');end if;else if not exists(select 1 from word_cards c join word_lists l on l.id=c.list_id where c.id=p_id and l.user_id=auth.uid())then raise exception'not allowed';end if;if p_rating is null then insert into word_card_states(user_id,word_card_id,unknown_flag)values(auth.uid(),p_id,p_unknown)on conflict(user_id,word_card_id)do update set unknown_flag=p_unknown,updated_at=now();insert into word_attempts(user_id,word_card_id,rating,unknown_flag,action)values(auth.uid(),p_id,null,p_unknown,'check');else days:=case p_rating when'again'then 0 when'hard'then 1 when'good'then 3 else 7 end;insert into word_card_states(user_id,word_card_id,last_rating,unknown_flag,review_count,due_at,next_review_date)values(auth.uid(),p_id,p_rating,p_unknown,1,now()+make_interval(days=>days),current_date+days)on conflict(user_id,word_card_id)do update set last_rating=p_rating,unknown_flag=p_unknown,review_count=word_card_states.review_count+1,due_at=now()+make_interval(days=>days),next_review_date=current_date+days,updated_at=now();insert into word_attempts(user_id,word_card_id,rating,unknown_flag,action)values(auth.uid(),p_id,p_rating,p_unknown,'review');end if;end if;end$$;
create or replace function public.submit_content(p_type text,p_id uuid)returns void language plpgsql security definer set search_path=public as $$begin if p_type='material'then update material_decks set visibility='submitted',is_public=false,submitted_at=now(),approved_at=null,rejected_reason=null,created_by_user_id=coalesce(created_by_user_id,auth.uid()),updated_at=now()where id=p_id and user_id=auth.uid();else update word_lists set visibility='submitted',is_public=false,submitted_at=now(),approved_at=null,rejected_reason=null,created_by_user_id=coalesce(created_by_user_id,auth.uid()),updated_at=now()where id=p_id and user_id=auth.uid();end if;if not found then raise exception'not allowed';end if;end$$;
create or replace function public.moderate_submission(p_type text,p_id uuid,p_approve boolean,p_reason text default null)returns void language plpgsql security definer set search_path=public as $$begin if not public.is_admin()then raise exception'admin only';end if;if p_type='material'then update material_decks set visibility=case when p_approve then'approved'else'rejected'end,is_public=p_approve,approved_at=case when p_approve then now()else null end,rejected_reason=case when p_approve then null else coalesce(p_reason,'却下されました')end,updated_at=now()where id=p_id and visibility='submitted';else update word_lists set visibility=case when p_approve then'approved'else'rejected'end,is_public=p_approve,approved_at=case when p_approve then now()else null end,rejected_reason=case when p_approve then null else coalesce(p_reason,'却下されました')end,updated_at=now()where id=p_id and visibility='submitted';end if;if not found then raise exception'not found';end if;end$$;
create or replace function public.library_items(p_query text default'',p_type text default'all')returns table(content_type text,id uuid,title text,creator_name text,item_count bigint,copy_count int,updated_at timestamptz,share_token text)language sql stable security definer set search_path=public as $$select'material',d.id,d.title,coalesce(p.display_name,'ユーザー'),(select count(*)from material_nodes n where n.deck_id=d.id and n.node_type='item'),d.copy_count,d.updated_at,d.share_token from material_decks d left join profiles p on p.id=d.created_by_user_id where d.visibility='approved'and(p_type in('all','material'))and(p_query=''or d.title ilike'%'||p_query||'%')union all select'cards',l.id,l.title,coalesce(p.display_name,'ユーザー'),(select count(*)from word_cards c where c.list_id=l.id),l.copy_count,l.updated_at,l.share_token from word_lists l left join profiles p on p.id=l.created_by_user_id where l.visibility='approved'and(p_type in('all','cards'))and(p_query=''or l.title ilike'%'||p_query||'%')order by updated_at desc$$;
create or replace function public.admin_submissions()returns table(content_type text,id uuid,title text,creator_name text,item_count bigint,copy_count int,updated_at timestamptz,share_token text,description text,submitted_at timestamptz,rejected_reason text)language sql stable security definer set search_path=public as $$select'material',d.id,d.title,coalesce(p.display_name,'ユーザー'),(select count(*)from material_nodes n where n.deck_id=d.id and n.node_type='item'),d.copy_count,d.updated_at,d.share_token,d.description,d.submitted_at,d.rejected_reason from material_decks d left join profiles p on p.id=d.created_by_user_id where d.visibility='submitted'and public.is_admin()union all select'cards',l.id,l.title,coalesce(p.display_name,'ユーザー'),(select count(*)from word_cards c where c.list_id=l.id),l.copy_count,l.updated_at,l.share_token,l.description,l.submitted_at,l.rejected_reason from word_lists l left join profiles p on p.id=l.created_by_user_id where l.visibility='submitted'and public.is_admin()order by submitted_at$$;
create or replace function public.copy_shared_material(p_token text)returns uuid language plpgsql security definer set search_path=public as $$declare source_id uuid;new_deck uuid;n record;new_node uuid;node_map jsonb:='{}';begin if auth.uid()is null then raise exception'login required';end if;select id into source_id from material_decks where share_token=p_token and visibility in('unlisted','approved');if source_id is null then raise exception'not found';end if;insert into material_decks(user_id,title,description,created_by_user_id)select auth.uid(),title,description,auth.uid()from material_decks where id=source_id returning id into new_deck;for n in with recursive tree as(select mn.*,0 depth from material_nodes mn where deck_id=source_id and parent_id is null union all select child.*,tree.depth+1 from material_nodes child join tree on child.parent_id=tree.id)select*from tree order by depth,order_index loop insert into material_nodes(deck_id,parent_id,node_type,title,memo,order_index)values(new_deck,case when n.parent_id is null then null else(node_map->>n.parent_id::text)::uuid end,n.node_type,n.title,n.memo,n.order_index)returning id into new_node;node_map:=node_map||jsonb_build_object(n.id::text,new_node::text);end loop;update material_decks set copy_count=copy_count+1 where id=source_id;return new_deck;end$$;
create or replace function public.copy_shared_cards(p_token text)returns uuid language plpgsql security definer set search_path=public as $$declare source_id uuid;new_list uuid;begin if auth.uid()is null then raise exception'login required';end if;select id into source_id from word_lists where share_token=p_token and visibility in('unlisted','approved');if source_id is null then raise exception'not found';end if;insert into word_lists(user_id,title,description,created_by_user_id)select auth.uid(),title,description,auth.uid()from word_lists where id=source_id returning id into new_list;insert into word_cards(list_id,card_id,front,back,memo,order_index)select new_list,card_id,front,back,memo,order_index from word_cards where list_id=source_id;update word_lists set copy_count=copy_count+1 where id=source_id;return new_list;end$$;
